import{_ as i,l as r,o as e,c as n,v as o,p as s,x as t,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"DoLa 层对比","description":"","frontmatter":{"title":"DoLa 层对比","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dola-decoding.md","filePath":"llm/dola-decoding.md","lastUpdated":1789023840000}'),h={name:"llm/dola-decoding.md"};function c(u,a,g,_,L,D){const l=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="dola-层对比" tabindex="-1">DoLa 层对比 <a class="header-anchor" href="#dola-层对比" aria-label="Permalink to &quot;DoLa 层对比&quot;">​</a></h1><div class="epigraph"><p>较晚的层更像在说事实，较早的层更像在说统计先验；把两者的 logits 对比后再采样，可以把「听起来对」从「有依据」里分开一点。</p><footer>—— Chuang et al., DoLa: Decoding by Contrasting Layers Improves Factuality in Large Language Models, ICLR 2024</footer></div><p><a href="/llm/mbr-decoding">上一课</a>在序列级用期望效用重排，前提是已经生成 \\(N\\) 条、还养得起度量。本课回到 <em>逐步</em>：一次前向里模型已经算完所有层，最后一层的 softmax 混着事实回忆与语言先验。Chuang 等人的 DoLa（Decoding by Contrasting Layers）用较晚层减去较早层的 logits，再在对比分布上解码，试图压低幻觉。它不改权重，也不做 MBR 的 \\(N\\) 次生成。后课的上下文感知解码把对比对象从「浅层」换成「无上下文的条件」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>幻觉经常不是词表随机噪声，而是先验太强：模型在看见实体名时，写出训练里更常见的属性，而不是当前层已经读到的事实。最后一层 logits 把「流畅续写」和「知识回忆」加在同一向量里。MBR 能在事后用度量挑，但延迟不可接受；需要一种 <em>同一次前向</em> 里的校正。缺口是：浅层与深层的信息差能否当作逐步的对比信号，而不另训模型。</p><p>DoLa 的假设是：早期层更接近下一 token 的语言统计，较晚层才把事实写入。对比 \\(z^{(L)}-z^{(j)}\\) 会放大两层不一致的方向。若假设失败——事实在中层已经写完、深层只做风格——对比会伤害流畅。本课只把这套对比写成解码算子，不把「哪一层存储事实」做成普遍神经科学结论。</p><p><span class="marginnote">对比发生在 logits 上，不是把两层的隐藏状态做差再投影。实现必须能取出中间层的 lm_head 投影（或预计算的层输出经同一 unembed）。没有这一钩子的服务引擎接不进 DoLa。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对当前前缀跑一遍 Transformer，记下最终层 logits \\(z^{(L)}\\) 与候选早层 \\(z^{(j)}\\)。\\(j\\) 可以静态取，或按层间 Jensen–Shannon 一类动态选「差得最多」的那层（DoLa 文中的动态策略）。对比分布</p> \\[p_{\\mathrm{DoLa}}(x_t)\\propto \\mathrm{softmax}\\big(F(z^{(L)}-z^{(j)})\\big), \\]<p>其中 \\(F\\) 是对过小logit 的截断，避免把两边都极低的噪声方向放大。然后按普通采样或贪心从 \\(p_{\\mathrm{DoLa}}\\) 取 token。温度、top-p 应作用在对比之后的分布上，顺序与<a href="/llm/sampling-temperature-topp">核采样</a>相同。</p><p>动态选层有成本：要看多层的分布差，等于多算几次 unembed。静态 \\(j\\) 更便宜，但跨模型和跨层深不迁移。不要把某一 7B 上的 \\(j=16\\) 写成常数。</p>',12)),(e(),s(m,null,{default:t(()=>[p(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%90%84%E5%B1%82%E9%9A%90%E8%97%8F%22%5D%20--%3E%20ZL%5B%22%E6%9C%80%E7%BB%88%E5%B1%82%20logits%22%5D%0A%20%20H%20--%3E%20ZJ%5B%22%E8%BE%83%E6%97%A9%E5%B1%82%20logits%22%5D%0A%20%20ZL%20--%3E%20SUB%5B%22%E5%AF%B9%E6%AF%94%20zL%20-%20zj%22%5D%0A%20%20ZJ%20--%3E%20SUB%0A%20%20SUB%20--%3E%20S%5B%22%E6%88%AA%E6%96%AD%E5%90%8E%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若深层把实体属性从上下文或参数记忆写入、浅层仍倾向高频共现，差值在正确属性 token 上为正、在共现干扰项上为负，逐步事实性可能上升。这与对比解码（Li 等人用 amateur 模型对比）同族，只是 amateur 换成了同一模型的浅层，省掉第二个模型。加速上，DoLa 几乎不增加 decode 步数，只增加取出中间层的带宽——相对 MBR 可忽略，相对纯采样仍有一截钩子开销。</p><p><span class="marginnote">事实性评测（TruthfulQA 一类）上的增益，不能外推到代码与数学：那里「浅层先验」往往是语法，对比可能把括号和关键字打歪。任务要分桶。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>DoLa 不是校准器：对比不提供置信度，只改排序。它也不替代检索；上下文里的证据若从未被任何层读进，差值帮不上。与<a href="/llm/speculative-decoding">投机解码</a>叠用时，草稿与目标必须走同一套对比，否则接受规则对的不是用户真正采样的分布。中间层取出与 <a href="/llm/kv-layout">KV 布局</a>无关，但与检查点是否暴露每层输出有关；张量并行下 unembed 可能切在词表维，对比要在归约之后做。</p><p>出处：Chuang et al., ICLR 2024。不要把 Contrastive Decoding（Li et al.）的 amateur 模型公式写进 DoLa。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DoLa 用最终层与较早层的 logits 差作为逐步分布，不改权重、不做 N 次生成。</li><li>假设是浅层偏先验、深层偏事实；失败时伤害流畅。</li><li>动态选层更稳、更贵；静态 \\(j\\) 不跨模型迁移。</li><li>钩子是中间层 unembed；服务引擎默认往往没有。</li><li>与投机叠用必须两边同一对比，否则无损证明失效。</li><li>后课把对比对象换成「有无上下文」。</li><li>出处：Chuang et al., ICLR 2024。</li></ul>',8))])}const B=i(h,[["render",c]]);export{E as __pageData,B as default};
